// Transform sales data
const data = $input.first().json;
const deals = data.deals || data || [];

const salesMetrics = {
  date: new Date().toISOString().split('T')[0],
  department: 'sales',

  // Pipeline metrics
  newDeals: deals.filter(d => d.stage === 'new').length,
  qualifiedDeals: deals.filter(d => d.stage === 'qualified').length,
  proposalsSent: deals.filter(d => d.stage === 'proposal').length,
  closedWon: deals.filter(d => d.stage === 'won').length,
  closedLost: deals.filter(d => d.stage === 'lost').length,

  // Value metrics
  pipelineValue: deals.reduce((sum, d) => sum + (d.value || 0), 0),
  wonValue: deals.filter(d => d.stage === 'won').reduce((sum, d) => sum + (d.value || 0), 0),
  averageDealSize: deals.length > 0 ? deals.reduce((sum, d) => sum + (d.value || 0), 0) / deals.length : 0,

  // Conversion
  winRate: deals.length > 0 ? (deals.filter(d => d.stage === 'won').length / deals.length * 100).toFixed(1) : 0
};

return {
  json: salesMetrics
};

// Transform marketing data
const data = $input.first().json;

const marketingMetrics = {
  date: new Date().toISOString().split('T')[0],
  department: 'marketing',

  // Traffic
  websiteVisits: data.visits || 0,
  uniqueVisitors: data.uniqueVisitors || 0,
  pageViews: data.pageViews || 0,
  bounceRate: data.bounceRate || 0,

  // Lead generation
  newLeads: data.leads || 0,
  mqls: data.mqls || 0,
  conversionRate: data.conversionRate || 0,
  costPerLead: data.spend && data.leads ? (data.spend / data.leads).toFixed(2) : 0,

  // Campaigns
  emailsSent: data.emailsSent || 0,
  emailOpenRate: data.openRate || 0,
  emailClickRate: data.clickRate || 0,

  // Social
  socialReach: data.socialReach || 0,
  socialEngagement: data.socialEngagement || 0,

  // Spend
  adSpend: data.adSpend || 0,
  contentPieces: data.contentPublished || 0
};

return {
  json: marketingMetrics
};

// Transform support data
const data = $input.first().json;

const supportMetrics = {
  date: new Date().toISOString().split('T')[0],
  department: 'support',

  // Volume
  ticketsCreated: data.created || 0,
  ticketsResolved: data.resolved || 0,
  ticketsOpen: data.open || 0,
  ticketsEscalated: data.escalated || 0,

  // Performance
  avgResponseTime: data.avgResponseTime || 0, // minutes
  avgResolutionTime: data.avgResolutionTime || 0, // hours
  firstContactResolution: data.fcrRate || 0,

  // Satisfaction
  csatScore: data.csat || 0,
  npsScore: data.nps || 0,

  // By channel
  emailTickets: data.emailTickets || 0,
  chatTickets: data.chatTickets || 0,
  phoneTickets: data.phoneTickets || 0,

  // SLA
  slaCompliance: data.slaCompliance || 0
};

return {
  json: supportMetrics
};

// Transform finance data
const data = $input.first().json;

const financeMetrics = {
  date: new Date().toISOString().split('T')[0],
  department: 'finance',

  // Revenue
  revenue: data.revenue || 0,
  recurringRevenue: data.mrr || 0,
  oneTimeRevenue: data.oneTime || 0,

  // Collections
  invoicesSent: data.invoicesSent || 0,
  invoicesPaid: data.invoicesPaid || 0,
  amountCollected: data.collected || 0,
  outstandingAR: data.arBalance || 0,
  dso: data.dso || 0, // Days Sales Outstanding

  // Expenses
  totalExpenses: data.expenses || 0,
  payroll: data.payroll || 0,
  operations: data.operations || 0,
  marketing: data.marketingSpend || 0,

  // Margins
  grossMargin: data.grossMargin || 0,
  netMargin: data.netMargin || 0,

  // Cash
  cashBalance: data.cash || 0,
  burnRate: data.burnRate || 0,
  runway: data.runway || 0 // months
};

return {
  json: financeMetrics
};

// Calculate cross-department KPIs
const items = $input.all().map(i => i.json);

const sales = items.find(i => i.department === 'sales') || {};
const marketing = items.find(i => i.department === 'marketing') || {};
const support = items.find(i => i.department === 'support') || {};
const finance = items.find(i => i.department === 'finance') || {};

const kpis = {
  date: new Date().toISOString().split('T')[0],

  // Executive KPIs
  revenue: finance.revenue || 0,
  mrr: finance.recurringRevenue || 0,
  grossMargin: finance.grossMargin || 0,

  // Growth KPIs
  newDeals: sales.closedWon || 0,
  newRevenue: sales.wonValue || 0,
  newLeads: marketing.newLeads || 0,
  leadToCustomerRate: marketing.newLeads > 0 ? ((sales.closedWon / marketing.newLeads) * 100).toFixed(2) : 0,

  // Customer KPIs
  csat: support.csatScore || 0,
  nps: support.npsScore || 0,
  ticketVolume: support.ticketsCreated || 0,
  resolutionTime: support.avgResolutionTime || 0,

  // Efficiency KPIs
  cac: marketing.newLeads > 0 ? ((marketing.adSpend || 0) / sales.closedWon).toFixed(2) : 0,
  ltv: 0, // Would need historical data

  // Health indicators
  pipelineHealth: sales.pipelineValue || 0,
  cashRunway: finance.runway || 0,
  slaCompliance: support.slaCompliance || 0,

  // Raw metrics for drill-down
  salesMetrics: sales,
  marketingMetrics: marketing,
  supportMetrics: support,
  financeMetrics: finance
};

// Calculate period-over-period changes (would need historical data)
kpis.trends = {
  revenueChange: 0, // placeholder
  leadsChange: 0,
  csatChange: 0
};

return {
  json: kpis
};

