// Generate formatted executive report
const data = $input.first().json;
const analysis = data.message?.content || '';

const report = {
  title: `Weekly Business Report - Week of ${new Date().toLocaleDateString()}`,
  generatedAt: new Date().toISOString(),
  period: 'weekly',
  content: analysis,
  metrics: data.metrics || {},
  charts: [
    { type: 'revenue_trend', url: `${$env.DASHBOARD_URL}/charts/revenue` },
    { type: 'pipeline_funnel', url: `${$env.DASHBOARD_URL}/charts/pipeline` },
    { type: 'customer_health', url: `${$env.DASHBOARD_URL}/charts/health` }
  ],
  dashboardUrl: $env.DASHBOARD_URL
};

return {
  json: report
};

